        col_vars = [grid[r][c] for r in range(L)]
        equations.append((col_vars, col_sums[c]))

    all_vars = set()
    for row in grid:
        for v in row:
            all_vars.add(v)

    val = {}

    while len(val) < len(all_vars):
        found = False
        for eq_vars, total in equations:
            unknowns = {}
            known_sum = 0
            for v in eq_vars:
                if v in val:
                    known_sum += val[v]
                else:
                    unknowns[v] = unknowns.get(v, 0) + 1

            if len(unknowns) == 1:
                v, count = next(iter(unknowns.items()))
                val[v] = (total - known_sum) // count
                found = True
                break
        if not found:
            break

    for v in sorted(all_vars):
        print(f"{v} {val[v]}")

if __name__ == '__main__':
    solve()
